<?php
/**
 * Design tokens: every :root variable the theme's CSS uses, one Customizer field each.
 * The list is generated by src/build.mjs into data/root-vars.json, with the original site's values as defaults.
 *
 * @package vulomail
 */

defined( 'ABSPATH' ) || exit;

/** [ ['name' => '--ink', 'value' => '#13141b', 'type' => 'color', 'group' => 'Colours'], … ] */
function vm_root_vars() {
	return vm_data( 'root-vars' );
}

function vm_var_setting_id( $name ) {
	return 'vm_var_' . str_replace( '-', '_', ltrim( $name, '-' ) );
}

/** Keeps a value safe inside a CSS declaration. */
function vm_sanitize_css_value( $value ) {
	$value = wp_strip_all_tags( (string) $value );
	$value = str_replace( array( '{', '}', ';', '<', '>' ), '', $value );
	return trim( $value );
}

/** The inline :root block printed after the theme CSS. */
function vm_root_vars_css() {
	$out = array();
	foreach ( vm_root_vars() as $v ) {
		$val = get_theme_mod( vm_var_setting_id( $v['name'] ), $v['value'] );
		$val = vm_sanitize_css_value( '' === $val ? $v['value'] : $val );
		if ( '--vm-container-7xl' === $v['name'] && vm_opt( 'use_astra_width' ) && function_exists( 'astra_get_option' ) ) {
			$w = (int) astra_get_option( 'site-content-width', 1200 );
			if ( $w > 0 ) {
				$val = $w . 'px';
			}
		}
		$out[] = $v['name'] . ':' . $val;
	}
	return ':root{' . implode( ';', $out ) . '}';
}

/** Customize → VuloMail → Design tokens. */
function vm_customize_root_vars( $wp_customize ) {
	$wp_customize->add_section(
		'vm_tokens',
		array(
			'title'       => __( 'Design tokens', 'vulomail' ),
			'panel'       => 'vm_panel',
			'priority'    => 90,
			'description' => __( 'Every CSS variable the theme uses. Defaults are the original site\'s values. Changing one changes the header, footer, every pattern and the blog.', 'vulomail' ),
		)
	);

	$wp_customize->add_setting( 'vm_tokens_reset', array( 'sanitize_callback' => '__return_empty_string', 'transport' => 'postMessage' ) );
	$wp_customize->add_control( new VM_Reset_Control( $wp_customize, 'vm_tokens_reset', array( 'section' => 'vm_tokens', 'priority' => 1 ) ) );

	$group = '';
	$i     = 10;
	foreach ( vm_root_vars() as $v ) {
		$id = vm_var_setting_id( $v['name'] );
		$wp_customize->add_setting(
			$id,
			array(
				'default'           => $v['value'],
				'sanitize_callback' => 'vm_sanitize_css_value',
				'transport'         => 'postMessage',
			)
		);
		$label = $v['name'] . ( $group !== $v['group'] ? '  ·  ' . $v['group'] : '' );
		$group = $v['group'];
		$args  = array(
			'section'     => 'vm_tokens',
			'label'       => $label,
			'description' => sprintf( /* translators: %s: default value */ __( 'Original: %s', 'vulomail' ), $v['value'] ),
			'priority'    => $i++,
		);
		if ( 'color' === $v['type'] ) {
			$wp_customize->add_control( new WP_Customize_Color_Control( $wp_customize, $id, $args ) );
		} else {
			$wp_customize->add_control( $id, $args + array( 'type' => 'text' ) );
		}
	}
}

add_action(
	'customize_register',
	function ( $wp_customize ) {
		if ( ! class_exists( 'VM_Reset_Control' ) ) {
			/** "Reset to original" button. */
			class VM_Reset_Control extends WP_Customize_Control { // phpcs:ignore Generic.Files.OneObjectStructurePerFile
				public $type = 'vm_reset';
				public function render_content() {
					echo '<button type="button" class="button vm-reset-tokens">' . esc_html__( 'Reset to original', 'vulomail' ) . '</button>';
					echo '<p class="description">' . esc_html__( 'Puts every token back to the original site\'s value. Press Publish to keep it.', 'vulomail' ) . '</p>';
				}
			}
		}
		vm_customize_root_vars( $wp_customize );
	},
	20
);

/** Live preview + reset button. */
add_action(
	'customize_controls_print_footer_scripts',
	function () {
		$map = array();
		foreach ( vm_root_vars() as $v ) {
			$map[ vm_var_setting_id( $v['name'] ) ] = $v['value'];
		}
		?>
		<script>
		(function (api) {
			var defaults = <?php echo wp_json_encode( $map ); ?>;
			document.addEventListener('click', function (e) {
				if (!e.target.classList.contains('vm-reset-tokens')) return;
				Object.keys(defaults).forEach(function (id) { if (api(id)) api(id).set(defaults[id]); });
			});
		})(wp.customize);
		</script>
		<?php
	}
);

add_action(
	'customize_preview_init',
	function () {
		$map = array();
		foreach ( vm_root_vars() as $v ) {
			$map[ vm_var_setting_id( $v['name'] ) ] = $v['name'];
		}
		add_action(
			'wp_footer',
			function () use ( $map ) {
				?>
				<script>
				(function (api) {
					var map = <?php echo wp_json_encode( $map ); ?>;
					Object.keys(map).forEach(function (id) {
						api(id, function (value) {
							value.bind(function (v) { document.documentElement.style.setProperty(map[id], v); });
						});
					});
				})(wp.customize);
				</script>
				<?php
			},
			99
		);
	}
);
